// TASK SETTINGS: the settings of this flow only (dry run per table).
// In: any message from an inject node. Out: the same message.
// It copies the shared settings from global context into flow context.
var DRY_RUN = {
  dim_asset: true,
  ref_target_seed: true,
  dim_reason: true,
  dim_product: true,
  dim_shift: true
};
var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}

var cfg = Object.assign({}, shared);
cfg.dryRun = DRY_RUN;
cfg.paths = {};
Object.keys(DRY_RUN).forEach(function (table) {
  cfg.paths[table] = shared.root + '/' + table + '/' + table + '.parquet';
});
cfg.assetIds = [];
shared.sites.forEach(function (site) {
  cfg.assetIds = cfg.assetIds.concat(site.assetIds);
});
flow.set('cfg', cfg);

var writing = Object.keys(DRY_RUN).filter(function (table) {
  return !DRY_RUN[table];
});
node.status({
  fill: writing.length ? 'green' : 'yellow',
  shape: 'dot',
  text: writing.length ? writing.length + ' table(s) WRITE' : 'DRY RUN'
});
return msg;

// Starts one run. In: any message from CONFIG (inject or test start).
// Out: msg.payload = the run day text YYYY-MM-DD, and msg.mode.
// A start like {start: 'YYYY-MM-DD'} fixes the day, otherwise it is today.
var day = new Date().toISOString().slice(0, 10);
var start = msg.payload;
if (start && typeof start === 'object' && start.start) {
  day = start.start;
}
msg.payload = day;
msg.mode = 'reference';
return msg;

// Builds the token request. The next node is an http request node.
// In: a day message {payload: 'YYYY-MM-DD', mode}.
// Out: msg.method, msg.url and msg.headers for the token POST.
var cfg = flow.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.day = msg.payload;
msg.loadedAt = Date.now();
msg.method = 'POST';
msg.url = 'https://' + cfg.tenantName +
  '.piam.eu1.mindsphere.io/oauth/token?grant_type=client_credentials';
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Keeps the token and builds the OEE asset list request (isConfigured,
// isManual). In: the token response. Out 1: the request for the http node.
// Out 2: a log message when the token request failed.
var cfg = flow.get('cfg');
var token = msg.payload && msg.payload.access_token;

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !token) {
  var failed = 'FAILED, NOTHING WRITTEN: token request failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}
msg.token = token;
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/assets';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Chooses the assets to read for the reference tables.
// In: the OEE asset list. Out 1: msg.payload = [{id, name, isManual,
// isConfigured, reasonTreeId}] for the split node. Out 2: a log message.
var cfg = flow.get('cfg');
var byId = {};
var skipped = [];
var targets = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
  var failed = 'FAILED, NOTHING WRITTEN: OEE asset list failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}

msg.payload.forEach(function (o) {
  byId[o.assetId] = o;
});
var ids = cfg.assetIds;
if (!ids || !ids.length) {
  ids = msg.payload.map(function (o) {
    return o.assetId;
  });
}
ids.forEach(function (id) {
  var o = byId[id];
  if (!o) {
    skipped.push(String(id).slice(0, 6) + '... not an OEE asset');
    return;
  }
  if (cfg.excludeNames.indexOf(o.name) >= 0) {
    skipped.push(o.name + ' excluded');
    return;
  }
  targets.push({
    id: id,
    name: o.name,
    isManual: o.isManual,
    isConfigured: o.isConfigured !== false,
    reasonTreeId: o.reasonTreeId || null
  });
});
msg.planSkipped = skipped;

if (!targets.length) {
  var nothing = 'NOTHING TO WRITE (no assets to read)';
  if (skipped.length) {
    nothing += ' | skipped: ' + skipped.join('; ');
  }
  return [null, logMessage(nothing)];
}
msg.payload = targets;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: targets.length + ' asset(s)'
});
return [msg, null];

// Builds the Asset Management request for one asset (to get hierarchyPath).
// In: one asset {id, isManual, name} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.asset = msg.payload;
msg.method = 'GET';
msg.url = cfg.gateway + '/api/assetmanagement/v3/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/hal+json'
};
delete msg.payload;
return msg;

// Saves the hierarchy of one asset and builds the OEE config request.
// In: the Asset Management response. Out 1: the config request.
// Out 2: the message for stage 3.4 when no config call is needed
// (details failed, asset excluded or asset not configured).
var cfg = flow.get('cfg');

// Names are root first. Tenant layout: [0] tenant, [1] region, [2] site,
// [3] area, [4] line, [5] machine. GT4 has no machine, so it is the line.
function hierarchyFromNames(names) {
  return {
    asset_name: names[names.length - 1] || null,
    site: names[2] || null,
    area: names[3] || null,
    line: names[4] || null,
    machine: names[5] || null
  };
}

var details = msg.payload;
msg.amFail = null;
msg.skip = null;
msg.h = null;
if (msg.statusCode !== 200 || !details || !details.name) {
  var text = msg.asset.name + ': asset details failed, HTTP ';
  msg.amFail = text + msg.statusCode;
} else {
  var names = (details.hierarchyPath || []).map(function (p) {
    return p.name;
  });
  names.push(details.name);
  msg.h = hierarchyFromNames(names);
  var excluded = cfg.excludeNames.indexOf(details.name) >= 0;
  var parentExcluded = names.slice(0, -1).some(function (n) {
    return cfg.excludeAncestorNames.indexOf(n) >= 0;
  });
  if (excluded || parentExcluded) {
    msg.skip = 'excluded';
  } else if (!msg.asset.isConfigured) {
    msg.skip = 'not configured';
  }
}

if (msg.amFail || msg.skip) {
  delete msg.payload;
  return [null, msg];
}
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/assets/' +
  encodeURIComponent(msg.asset.id) + '/config';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Saves the config of one asset and builds the thresholds request.
// In: the OEE config response. Out: msg.configInfo (status and the calendar
// and product collection ids) plus the request for the thresholds call.
var cfg = flow.get('cfg');
var config = msg.payload || {};
msg.configInfo = {
  status: msg.statusCode,
  calendarId: config.calendarId || null,
  productCollectionId: config.productCollectionId || null
};
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Builds the ref_target_seed item (one row per KPI) of one asset.
// In: the thresholds response, or no payload when the asset was skipped.
// Out: msg.targetItem = {name, failed, skipped, rows}. is_set = above 0.
var KPI_NAMES = [
  'OEE',
  'Availability',
  'Performance',
  'Quality'
];
var asset = msg.asset;
var body = msg.payload || {};
var item = {
  name: asset.name,
  failed: null,
  skipped: null,
  rows: []
};

function valueOf(list, kpi) {
  var found = null;
  (list || []).forEach(function (entry) {
    if (entry.name === kpi && typeof entry.value === 'number') {
      found = entry.value;
    }
  });
  return found;
}

if (msg.amFail) {
  item.failed = msg.amFail;
} else if (msg.skip) {
  item.skipped = asset.name + ' ' + msg.skip;
} else if (msg.statusCode !== 200 || !body.thresholds) {
  var text = asset.name + ': thresholds failed, HTTP ';
  item.failed = text + msg.statusCode;
} else {
  KPI_NAMES.forEach(function (kpi) {
    var warning = valueOf(body.thresholds.warnings, kpi);
    var error = valueOf(body.thresholds.errors, kpi);
    item.rows.push({
      asset_id: asset.id,
      asset_name: asset.name,
      kpi: kpi,
      warning: warning,
      error: error,
      is_set: warning > 0 || error > 0,
      loaded_at: msg.loadedAt
    });
  });
}
msg.targetItem = item;
delete msg.payload;
return msg;

// Builds the dim_asset item (one row) of one asset.
// In: msg.h (hierarchy), msg.configInfo and msg.asset. An unconfigured
// asset is kept, with empty ids. Out: msg.dimItem = {name, failed, skipped,
// rows}.
var asset = msg.asset;
var info = msg.configInfo || {};
var item = {
  name: asset.name,
  failed: null,
  skipped: null,
  rows: []
};

var isManual = null;
if (asset.isManual !== null && asset.isManual !== undefined) {
  isManual = !!asset.isManual;
}

if (msg.amFail) {
  item.failed = msg.amFail;
} else if (msg.skip === 'excluded') {
  item.skipped = asset.name + ' excluded';
} else if (asset.isConfigured && info.status !== 200) {
  var text = asset.name + ': asset config failed, HTTP ';
  item.failed = text + info.status;
} else {
  item.rows.push({
    asset_id: asset.id,
    asset_name: msg.h.asset_name,
    site: msg.h.site,
    area: msg.h.area,
    line: msg.h.line,
    machine: msg.h.machine,
    is_manual: isManual,
    is_configured: asset.isConfigured,
    calendar_id: info.calendarId || null,
    product_collection_id: info.productCollectionId || null,
    reason_tree_id: asset.reasonTreeId,
    loaded_at: msg.loadedAt
  });
}
msg.dimItem = item;
return msg;

// Builds the id items for the product, calendar and reason tables.
// In: msg.asset, msg.amFail, msg.skip, msg.configInfo, msg.dimItem and
// msg.targetItem. Out: msg.payload = {dim, target, product, calendar,
// reason} for the join. An id item is {name, value, failed, skipped}.
var asset = msg.asset;
var info = msg.configInfo || {};
var configFailed = !msg.amFail && !msg.skip && info.status !== 200;

function idItem(value) {
  var item = {
    name: asset.name,
    value: null,
    failed: null,
    skipped: null
  };
  if (msg.amFail) {
    item.failed = msg.amFail;
  } else if (msg.skip) {
    item.skipped = asset.name + ' ' + msg.skip;
  } else {
    item.value = value || null;
  }
  return item;
}

function configItem(value) {
  var item = idItem(value);
  if (configFailed) {
    item.failed = asset.name + ': config failed, HTTP ' + info.status;
  }
  return item;
}

msg.payload = {
  dim: msg.dimItem,
  target: msg.targetItem,
  product: configItem(info.productCollectionId),
  calendar: configItem(info.calendarId),
  reason: idItem(asset.reasonTreeId)
};
delete msg.dimItem;
delete msg.targetItem;
return msg;

// Splits the asset bundles into one message per table.
// In: msg.payload = array of {dim, target, product, calendar, reason}.
// Out 1 to 5: the items for dim_asset, ref_target_seed, product collection
// ids, calendar ids and reason tree ids.
var KEYS = [
  'dim',
  'target',
  'product',
  'calendar',
  'reason'
];
var bundles = msg.payload;

function messageFor(key) {
  var copy = Object.assign({}, msg);
  copy.payload = bundles.map(function (bundle) {
    return bundle[key];
  });
  return copy;
}

node.status({
  fill: 'blue',
  shape: 'dot',
  text: bundles.length + ' asset(s)'
});
return KEYS.map(messageFor);

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Decides what happens with the table dim_asset.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'dim_asset';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['dim_asset'];
msg.filename = msg.path.split('/').pop();
return msg;

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Decides what happens with the table ref_target_seed.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'ref_target_seed';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['ref_target_seed'];
msg.filename = msg.path.split('/').pop();
return msg;

// Collects the distinct ids of the assets.
// In: msg.payload = array of items {name, value, failed, skipped}.
// Out 1: msg.ids (list of ids). Out 2: a log line when an item failed or
// there is no id at all.
var seen = {};
var ids = [];
var failures = [];
var without = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

msg.payload.forEach(function (item) {
  if (item.failed) {
    failures.push(item.failed);
    return;
  }
  if (item.skipped) {
    return;
  }
  var id = item.value;
  if (!id) {
    without.push(item.name);
    return;
  }
  if (!seen[id]) {
    seen[id] = true;
    ids.push(id);
  }
});

if (failures.length) {
  var failed = 'FAILED, NOTHING WRITTEN: ' + failures.join(' | ');
  return [null, logMessage(failed)];
}
if (!ids.length) {
  var nothing = 'NOTHING TO WRITE (no ids found)';
  if (without.length) {
    nothing += ' | assets without id: ' + without.join(', ');
  }
  return [null, logMessage(nothing)];
}
if (without.length) {
  var note = ' | assets without id: ' + without.join(', ');
  msg.planSkipped = (msg.planSkipped || []).concat(note);
}
msg.ids = ids;
delete msg.payload;
return [msg, null];

// Builds the request for the master list that holds the names of the ids.
// In: msg.ids. Out: msg.method, msg.url and msg.headers for the http node.
// The list path is set in LIST_PATH.
var LIST_PATH = 'reasontrees';
var cfg = flow.get('cfg');
msg.method = 'GET';
msg.url = cfg.gateway + '/api/oee/v3/' + LIST_PATH;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
return msg;

// Matches the wanted ids (msg.ids) with the master list, to get the names.
// In: the list response. Out 1: msg.payload = [{id, name, extra}] for the
// split node. Out 2: a log line. LIST_KEY is the array inside the response.
var LIST_KEY = 'reasonTrees';
var NAME_FIELD = 'name';
var EXTRA_FIELD = '';
var byId = {};
var targets = [];
var notInList = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

var list = msg.payload;
if (LIST_KEY && list) {
  list = list[LIST_KEY];
}
if (msg.statusCode !== 200 || !Array.isArray(list)) {
  var failed = 'FAILED, NOTHING WRITTEN: master list failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}

list.forEach(function (entry) {
  byId[entry.id] = entry;
});
msg.ids.forEach(function (id) {
  var entry = byId[id];
  if (!entry) {
    notInList.push(String(id).slice(0, 6) + '...');
  }
  targets.push({
    id: id,
    name: entry ? entry[NAME_FIELD] : null,
    extra: entry && EXTRA_FIELD ? entry[EXTRA_FIELD] : null
  });
});
if (notInList.length) {
  var note = ' | not in master list: ' + notInList.join(', ');
  msg.planSkipped = (msg.planSkipped || []).concat(note);
}
msg.payload = targets;
delete msg.ids;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: targets.length + ' id(s)'
});
return [msg, null];

// Builds the GET request for one id (reason tree, collection or calendar).
// In: one target {id, name, extra} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var PATH_BEFORE = 'reasontrees/';
var PATH_AFTER = '/reasons';
var WITH_WINDOW = false;
var DAY_MS = 86400000;
var cfg = flow.get('cfg');
msg.target = msg.payload;
var url = cfg.gateway + '/api/oee/v3/' + PATH_BEFORE +
  encodeURIComponent(msg.target.id) + PATH_AFTER;

// Calendar events are read for a window that starts on the run day.
if (WITH_WINDOW) {
  var from = Date.parse(msg.day + 'T00:00:00.000Z');
  var to = from + cfg.calendarWindowDays * DAY_MS;
  url += '?from=' + new Date(from).toISOString();
  url += '&to=' + new Date(to).toISOString();
}
msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Builds the dim_reason rows of one reason tree.
// In: the reasons response (flat list with parentId) and msg.target.
// Out: msg.payload = an item {name, failed, skipped, rows} for the join.
var MAX_DEPTH = 20;
var target = msg.target;
var label = target.name || String(target.id).slice(0, 6) + '...';
var item = {
  name: label,
  failed: null,
  skipped: null,
  rows: []
};

var reasons = msg.payload && msg.payload.reasons;
if (msg.statusCode !== 200 || !Array.isArray(reasons)) {
  var text = 'reason tree ' + label + ' failed, HTTP ';
  item.failed = text + msg.statusCode;
  msg.payload = item;
  return msg;
}

var byId = {};
reasons.forEach(function (r) {
  byId[r.id] = r;
});

// Names from the top level down to the reason, found through parentId.
function pathOf(reason) {
  var names = [];
  var current = reason;
